SELECT a.id, a.product_id, a.product_key, a.third_platform, a.third_configuration, a.company_no, a.classified_id, a.configuration, a.network_union_id, a.device_node, a.message_protocol, a.name AS name, a.creator_id, a.tenant_id, a.product_description AS describe, a.store_policy, a.store_policy_configuration, a.transport_protocol, a.photo_url, a.create_time, a.state, count(b.id) AS devNum FROM iot_product a LEFT JOIN iot_device b ON a.product_key = b.product_key LEFT JOIN iot_user au ON a.creator_id = au.union_id
AND a.product_id = #{productId}
AND a.product_key LIKE ('%' || #{productKey} || '%')
AND a.third_platform LIKE ('%' || #{thirdPlatform} || '%')
AND a.network_union_id = #{networkUnionId}
AND a.device_node = #{deviceNode}
AND a.gw_product_key = #{gwProductKey}
AND a.classified_id = #{classifiedId}
AND a.classified_name LIKE ('%' || #{classifiedName} || '%')
AND a.company_no LIKE ('%' || #{companyNo} || '%')
AND a.message_protocol = #{messageProtocol}
AND a.name LIKE ('%' || #{name} || '%')
AND (a.tenant_id = #{tenantId} OR ((a.tenant_id is null or a.tenant_id = '') AND au.tenant_id = #{tenantId}))
AND a.creator_id = #{creatorId}
AND ( b.tenant_id = #{tenantId}
OR ((b.tenant_id is null or b.tenant_id = '') AND b.creator_id in
#{scopeUnionId}
)
)
AND a.product_description = #{describe}
AND a.store_policy = #{storePolicy}
AND a.transport_protocol LIKE ('%' || #{transportProtocol} || '%')
AND a.state = #{state}
GROUP BY a.id, a.product_id, a.product_key, a.third_platform, a.third_configuration, a.company_no, a.classified_id, a.configuration, a.network_union_id, a.device_node, a.message_protocol, a.name, a.creator_id, a.product_description, a.store_policy, a.store_policy_configuration, a.transport_protocol, a.photo_url, a.create_time, a.state
HAVING count(b.id) > 0
ORDER BY a.id DESC

SELECT a.id,
       a.tags,
       a.product_id,
       a.product_key,
       a.network_union_id,
       a.third_platform,
       a.company_no,
       a.device_node,
       a.name AS name,
       a.creator_id,
       a.tenant_id,
       a.transport_protocol,
       a.photo_url,
       a.create_time,
       a.state,
       a.metadata,
       COALESCE(d.dev_num, 0) AS devNum
FROM iot_product a
  LEFT JOIN iot_user au ON a.creator_id = au.union_id
  LEFT JOIN (
    SELECT di.product_key,
           COUNT(di.id) AS dev_num
    FROM iot_device di


        (
        di.tenant_id = #{tenantId}

          or ((di.tenant_id is null or di.tenant_id = '') and di.creator_id in

            #{scopeUnionId}

          )

        )



    GROUP BY di.product_key
  ) d ON a.product_key = d.product_key


    a.product_id = #{productId}


    AND a.product_key LIKE CONCAT('%', #{productKey}, '%')


    AND a.third_platform LIKE CONCAT('%', #{thirdPlatform}, '%')


    AND a.network_union_id = #{networkUnionId}


    AND a.device_node = #{deviceNode}


    AND a.gw_product_key = #{gwProductKey}


    AND a.classified_id = #{classifiedId}


    AND a.classified_name LIKE CONCAT('%', #{classifiedName}, '%')


    AND a.company_no LIKE CONCAT('%', #{companyNo}, '%')


    AND a.message_protocol = #{messageProtocol}


    AND (a.name LIKE CONCAT('%', #{name}, '%') OR a.product_key LIKE CONCAT('%', #{name}, '%'))


    AND (a.tenant_id = #{tenantId}
    OR ((a.tenant_id is null or a.tenant_id = '') AND au.tenant_id = #{tenantId}))

  AND a.creator_id = #{creatorId}

    AND a.product_description = #{describe}


    AND a.store_policy = #{storePolicy}


    AND a.transport_protocol LIKE CONCAT('%', #{transportProtocol}, '%')


    AND a.state = #{state}


    AND

      position(',' || #{tag} || ',' in ',' || COALESCE(a.tags, '') || ',') > 0



ORDER BY a.create_time DESC

SELECT a.id, a.product_id, a.product_key, a.third_platform, a.third_configuration, a.company_no, a.classified_id, a.configuration, a.network_union_id, a.device_node, a.message_protocol, a.name AS name, a.creator_id, a.tenant_id, a.product_description AS describe, a.store_policy, a.store_policy_configuration, a.transport_protocol, a.photo_url, a.create_time, a.state, a.metadata, a.third_down_request, COUNT(b.id) AS devNum, MAX(p.name) AS protocolName2, MAX(p.state) AS protocolState, MAX(p.type) AS protocolType, MAX(p.configuration) AS protocolConfiguration, MAX(p.example) AS protocolExample, MAX(n.type) AS networkType, MAX(n.name) AS networkName, MAX(n.description) AS networkDescription, MAX(n.configuration) AS networkConfiguration, MAX(n.state) AS networkState FROM iot_product a LEFT JOIN iot_device b ON a.product_key = b.product_key LEFT JOIN iot_user au ON a.creator_id = au.union_id LEFT JOIN iot_device_protocol p ON a.product_key = p.id LEFT JOIN iot_network n ON n.union_id = a.product_key
AND a.id = #{id}
AND a.product_id = #{productId}
AND a.product_key LIKE CONCAT('%', #{productKey}, '%')
AND (a.name LIKE CONCAT('%', #{name}, '%') OR a.product_key LIKE CONCAT('%', #{name}, '%'))
AND (a.tenant_id = #{tenantId} OR ((a.tenant_id is null or a.tenant_id = '') AND au.tenant_id = #{tenantId}))
AND a.creator_id = #{creatorId}
AND ( b.tenant_id = #{tenantId}
OR ((b.tenant_id is null or b.tenant_id = '') AND b.creator_id in
#{scopeUnionId}
)
)
GROUP BY a.id, a.product_id, a.product_key, a.third_platform, a.third_configuration, a.company_no, a.classified_id, a.configuration, a.network_union_id, a.device_node, a.message_protocol, a.name, a.creator_id, a.product_description, a.store_policy, a.store_policy_configuration, a.transport_protocol, a.photo_url, a.create_time, a.state, a.metadata, a.third_down_request
HAVING COUNT(b.id) > 0
ORDER BY a.create_time DESC

